// L'ancienne forme du switch : des 'case' suivis de deux-points.
int jour = 3;
String nom;

switch (jour) {
    case 1:
        nom = "lundi";
        break; // 'break' = "sors du switch maintenant".
    case 2:
        nom = "mardi";
        break;
    case 3:
        nom = "mercredi";
        break;
    default:
        nom = "inconnu";
}

System.out.println(nom); // mercredi

int jour = 1;
String nom;

switch (jour) {
    case 1:
        nom = "lundi";
        // OUPS : pas de break ici !
    case 2:
        nom = "mardi"; // on "tombe" dans ce case et nom est ecrase
        break;
    default:
        nom = "inconnu";
}

// On attendait "lundi", mais on obtient "mardi" :
// faute de break, l'execution a continue dans le case 2.
System.out.println(nom); // mardi

int jour = 3;

// Le switch se calcule en une valeur, affectee directement a 'nom'.
String nom = switch (jour) {
    case 1 -> "lundi";
    case 2 -> "mardi";
    case 3 -> "mercredi";
    default -> "inconnu";
};
// Noter le point-virgule final : c'est une expression affectee a une variable.

System.out.println(nom); // mercredi

// Pas de break, pas de fall-through : chaque case -> est isole.

