int jour = 6;

String type = switch (jour) {
    case 6, 7 -> "week-end"; // cas simple : une valeur directe
    default -> {
        // Ici on a plusieurs lignes, donc un bloc entre accolades.
        System.out.println("Calcul pour un jour de semaine...");
        String resultat = "jour " + jour + " (semaine)";
        yield resultat; // 'yield' fournit la valeur du switch
    }
};

System.out.println(type);

int points = 2;

int bonus = switch (points) {
    // Cas court : valeur directe apres la fleche, SANS yield.
    case 0 -> 0;
    case 1 -> 5;
    // Cas long : un bloc { } donc on DOIT utiliser yield.
    case 2 -> {
        int base = 5;
        int extra = points * 3;
        yield base + extra; // la valeur renvoyee par ce cas
    }
    default -> 0;
};

System.out.println(bonus); // 11

