int mois = 4;

int jours = switch (mois) {
    // Plusieurs etiquettes pour un meme cas, separees par des virgules.
    case 1, 3, 5, 7, 8, 10, 12 -> 31;
    case 4, 6, 9, 11 -> 30;
    case 2 -> 28; // on simplifie, sans annee bissextile
    default -> throw new IllegalArgumentException("mois invalide : " + mois);
};

System.out.println(jours); // 30

