// Choisir un tarif selon le type de client, avec des if/else.
String type = "etudiant";
int tarif;

if (type.equals("enfant")) {
    tarif = 5;
} else if (type.equals("etudiant")) {
    tarif = 8;
} else if (type.equals("senior")) {
    tarif = 7;
} else {
    tarif = 12;
}

System.out.println(tarif); // 8

// Exactement la meme logique, en switch expression.
String type = "etudiant";

int tarif = switch (type) {
    case "enfant" -> 5;
    case "etudiant" -> 8;
    case "senior" -> 7;
    default -> 12; // remplace le 'else' final
};

System.out.println(tarif); // 8

// Plus court, aligne, et le compilateur verifie qu'un cas couvre tout.

